    },
    "profileRelease": {
      "type": "string",
      "pattern": "^[0-9]{4}\\.[0-9]+$",
      "description": "a Profile release in YYYY.serial form"
    },
    "typeDefinition": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "description"
      ],
      "properties": {
        "name": {
          "$ref": "#/$defs/text"
        },
        "description": {
          "$ref": "#/$defs/text"
        }
      }
    },
    "tagDefinition": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "description"
      ],
      "properties": {
        "name": {
          "$ref": "#/$defs/text"
        },
